mapper.select:
SELECT * FROM CHAT_REQUEST
WHERE FROM_USER = #{fromUser}
AND TO_USER = #{toUser}
AND STATUS = 'PENDING'
LIMIT 1

mapper.update:
UPDATE CHAT_REQUEST
SET STATUS = #{status}
WHERE REQUEST_ID = #{requestId}

UPDATE CHAT_MESSAGE
SET IS_READ = 'Y'
WHERE ROOM_ID = #{roomId}
AND SENDER_ID != #{userId}
AND IS_READ = 'N'

mapper.delete:
DELETE FROM USER_BLOCK
WHERE BLOCKER_ID = #{blockerId}
AND BLOCKED_ID = #{blockedId}

mapper.select:
SELECT COUNT(*) FROM USER_BLOCK
WHERE BLOCKER_ID = #{blockerId}
AND BLOCKED_ID = #{blockedId}

mapper.update:
UPDATE CHAT_MESSAGE
SET IS_DELETED = 'Y',
    CONTENT = '삭제된 메시지입니다',
    MESSAGE_TYPE = 'TEXT'
WHERE MESSAGE_ID = #{messageId}
  AND ROOM_ID = #{roomId}
  AND SENDER_ID = #{userId}
  AND IS_DELETED = 'N'
